# The symmetry behind 45 deg: polarity (Hodge duality) of Euclidean de Sitter relative to the observer's Killing plane
# (papers/restart/31-theta-sphere.md, section "Symmetry"). D1-D6.
# Euclidean dS_4 = S^4 of radius l in R^5. The observer family is generated by the bivector B = e0 e4; its Hodge dual B* = B I5 spans the
# horizon directions. A point X splits as X = P_B(X) + P_B*(X), radii rho = |P_B X|, d = |P_B* X|, tan(chi) = d/rho, a = H tan(chi).
# Run: uv run --with sympy python ga_theta_duality_check.py
import sympy as sp
from ga_core import *

E5 = {k: 1 for k in range(5)}
I5 = {(0, 1, 2, 3, 4): 1}
l, chi, a, H, u = sp.symbols('l chi a H u', positive=True)
rev = lambda M: {k: (v if len(k) % 4 in (0, 1) else -v) for k, v in M.items()}
B = {(0, 4): 1}
Bs = gp(B, I5, E5)                                                   # Hodge dual of the Killing plane
inv = lambda M: scal(1 / gp(M, rev(M), E5)[()], rev(M))
proj = lambda X, M: grade(gp(grade(gp(X, M, E5), len(next(iter(M))) - 1), inv(M), E5), 1)   # (X . M) M^-1
X = vec([l * sp.cos(chi) * sp.cos(u), l * sp.sin(chi), 0, 0, l * sp.cos(chi) * sp.sin(u)])
n2 = lambda V: sp.simplify(gp(V, V, E5).get((), 0))
PB, PBs = proj(X, B), proj(X, Bs)

# D1 B* is the trivector e1 e2 e3 (up to sign); the rotor exp(B tau/2) fixes exactly span(B*), so S^4 ∩ span(B*) is the horizon S^2;
#    X = P_B X + P_B* X with |P_B X| = rho = l cos(chi), |P_B* X| = d = l sin(chi).
Rt = add({(): sp.cos(u / 2)}, scal(-sp.sin(u / 2), B))
simp = lambda M: {k: w for k, w in ((k, sp.simplify(v)) for k, v in M.items()) if w != 0}
fixed = all(simp(gp(gp(Rt, {(k,): 1}, E5), rev(Rt), E5)) == {(k,): 1} for k in (1, 2, 3))
ok(f"D1 B* = B I5 = {Bs}; rotor of B fixes e1,e2,e3 = span(B*) (the horizon): {fixed}; |P_B X|^2 = {n2(PB)}, |P_B* X|^2 = {n2(PBs)}, sum = l^2",
   set(Bs) == {(1, 2, 3)} and fixed and sp.simplify(n2(PB) - l**2 * sp.cos(chi)**2) == 0 and sp.simplify(n2(PBs) - l**2 * sp.sin(chi)**2) == 0
   and simp(add(PB, PBs, scal(-1, X))) == {})

# D2 the duality B <-> B* (polarity of the sphere: worldline circle <-> horizon sphere) swaps the two projections, so tan(chi) -> cot(chi),
#    chi -> pi/2 - chi, a -> H^2/a, Unruh part <-> horizon part. Its only fixed point is chi = 45 deg, a = H.
tan_dual = sp.sqrt(n2(PB) / n2(PBs))
ok(f"D2 swapping B <-> B*: tan(chi') = |P_B X|/|P_B* X| = {sp.simplify(tan_dual)} = cot(chi); a' = H cot(chi) = H^2/a; fixed point chi = pi/4",
   sp.simplify(tan_dual**2 - sp.cot(chi)**2) == 0 and [x for x in sp.solve(sp.tan(chi) - sp.cot(chi), chi) if 0 < x < sp.pi / 2] == [sp.pi / 4])

# D3 how T(a) = sqrt(a^2+H^2)/2pi transforms: T(H^2/a) = (H/a) T(a); the invariant is T/sqrt(aH), minimal at the self-dual point,
#    where it equals theta = sqrt2/(2pi) (AM-GM: T^2 = T_U^2 + T_GH^2 >= 2 T_U T_GH).
T = lambda x: sp.sqrt(x**2 + H**2) / (2 * sp.pi)
g = T(a) / sp.sqrt(a * H)
ok(f"D3 T(H^2/a) = (H/a) T(a): {sp.simplify(T(H**2 / a) - H / a * T(a)) == 0}; T/sqrt(aH) invariant under a <-> H^2/a, "
   f"minimum at a = {sp.solve(sp.diff(g, a), a)} with value {sp.simplify(g.subs(a, H))} = theta",
   sp.simplify(T(H**2 / a) - H / a * T(a)) == 0 and sp.simplify(g - g.subs(a, H**2 / a)) == 0
   and sp.solve(sp.diff(g, a), a) == [H] and sp.simplify(g.subs(a, H) - sp.sqrt(2) / (2 * sp.pi)) == 0)

# D4 inverse temperatures of a dual pair add in quadrature to the de Sitter one: beta(a)^2 + beta(H^2/a)^2 = beta_dS^2 (rho^2 + d^2 = l^2).
beta = lambda x: 1 / T(x)
ok(f"D4 beta(a)^2 + beta(H^2/a)^2 = {sp.simplify(beta(a)**2 + beta(H**2 / a)**2)} = (2 pi/H)^2 = beta_dS^2; self-dual beta = beta_dS/sqrt2",
   sp.simplify(beta(a)**2 + beta(H**2 / a)**2 - (2 * sp.pi / H)**2) == 0)

# D5 curvature language: the orbit circle in R^5 has curvature 1/rho; its normal part (the sphere) is 1/l, its geodesic part is a.
#    45 deg <=> geodesic curvature = normal curvature: the 5D acceleration bisects the tangent acceleration and the normal X.
rho = l * sp.cos(chi)
kg = sp.sqrt(1 / rho**2 - 1 / l**2)
ok(f"D5 geodesic curvature kg = sqrt(1/rho^2 - 1/l^2) = {sp.simplify(kg)}, normal curvature 1/l: equal at chi = pi/4",
   sp.simplify(kg.subs(chi, sp.pi / 4) - 1 / l) == 0 and sp.simplify(kg**2 - sp.tan(chi)**2 / l**2) == 0)

# D6 why S^3 differs from S^4: polarity is an isometry only when dim B = dim B* (n+1 = 4: B and B* are both planes). Then the self-dual
#    tube is also the minimal one (Clifford torus, 45 deg). In R^5 (2 vs 3) it is not, and the minimal tube moves to 54.7 deg (H5).
r = sp.symbols('r', positive=True)
mins = {n: [s for s in sp.solve(sp.diff(r * (1 - r**2) ** sp.Rational(n - 2, 2), r), r) if s.is_positive and s < 1][0] for n in (3, 4)}
ok(f"D6 grade of B* in R^(n+1): n=3 -> {5 - 2 - 1} (plane, isometry), n=4 -> 3 (not); minimal-tube radius {mins}: 1/sqrt2 only for n=3",
   mins[3] == 1 / sp.sqrt(2) and mins[4] == 1 / sp.sqrt(3) and len(next(iter(Bs))) == 3)
